            aOrbiterA = ((aWandererA + RotL64(aPrevious, 47U)) + RotL64(aCarry, 23U)) + 0x13E9A0498DC44575ULL;
            aOrbiterD = (((aWandererK + RotL64(aScatter, 39U)) + 0x956DD4F88088AC98ULL) + aOASaltA[(((511U - aIndex) + 63U)) & S_SALT1]) + aNonceWordK;
            aOrbiterG = (((aWandererE + RotL64(aIngress, 18U)) + RotL64(aCarry, 43U)) + 0x42497BE14968166BULL) + aNonceWordI;
