            aOrbiterC = ((aWandererJ + RotL64(aPrevious, 4U)) + 0x6E6B784CC26CA3B3ULL) + aNonceWordL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x33D622FBDEAD4DBFULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x3DECED149589C411ULL;
