            aOrbiterG = RotL64((aOrbiterG * 0x9F592BAFEC579261ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xD7EC54F491AF181CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x4297E907A7B47CF6ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xC935038A4949E953ULL), 27U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xDB4EC799C70599B4ULL;
            aOrbiterC = (((aOrbiterC ^ aOrbiterD) ^ 0x3588873B399C8FCDULL) ^ aOUSaltH[((aIndex + 315U)) & S_SALT1]) ^ aNonceWordO;
