            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x332614DC6E6492FBULL) ^ aOUSaltB[((aIndex + 479U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xDA50BAF6EA7D4987ULL), 51U);
            //
            aOrbiterI = (((aOrbiterI + aOrbiterD) + 0x586924B0A6A53574ULL) + aOUSaltA[(((511U - aIndex) + 123U)) & S_SALT1]) + aNonceWordM;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xBE725AA68E843BE7ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xEEC0D891CBB62697ULL), 43U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x76CD2F55C15C19DBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x236AD674CA7C84D6ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xA7D184C589D8795DULL), 23U);
