            aWandererK = aWandererK ^ ((RotL64(aIngress, 35U) + RotL64(aOrbiterF, 39U)) + aOrbiterD);
            aWandererJ = aWandererJ + ((((RotL64(aPrevious, 5U) + aOrbiterA) + RotL64(aOrbiterB, 53U)) + RotL64(aCarry, 27U)) + aWUSaltG[((aIndex + 84U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aCross, 57U) + aOrbiterG) + RotL64(aOrbiterA, 24U)) + aNonceWordC);
