            aWandererA = aWandererA + ((((RotL64(aCross, 11U) + aOrbiterB) + RotL64(aOrbiterF, 29U)) + RotL64(aCarry, 35U)) + aWUSaltH[(((511U - aIndex) + 506U)) & S_SALT1]);
