            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x58096E4CDE245394ULL) + aOUSaltE[((aIndex + 217U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x62A775446F9B2C0EULL) ^ aOUSaltG[((aIndex + 371U)) & S_SALT1];
