            //
            aOrbiterI = ((aWandererF + RotL64(aIngress, 5U)) + 0xD27F7A58CF93719CULL) + aOASaltG[((aIndex + 338U)) & S_SALT1];
            aOrbiterB = ((aWandererG + RotL64(aScatter, 34U)) + RotL64(aCarry, 23U)) + 0xDA977893D1468D65ULL;
            aOrbiterA = ((aWandererH + RotL64(aCross, 47U)) + RotL64(aCarry, 39U)) + 0xD1252B264978FC29ULL;
            aOrbiterK = ((aWandererE + RotL64(aPrevious, 39U)) + RotL64(aCarry, 57U)) + 0x14735E5D812A8F7CULL;
            aOrbiterC = ((aWandererI + RotL64(aIngress, 29U)) + 0x6C70D6101CC2D6A4ULL) + aOASaltH[((aIndex + 387U)) & S_SALT1];
            aOrbiterH = (aWandererD + RotL64(aScatter, 13U)) + 0x77E8A39107D4AAB7ULL;
            aOrbiterF = (aWandererB + RotL64(aCross, 18U)) + 0x115D7949A4D5B0D5ULL;
            aOrbiterJ = (aWandererC + RotL64(aPrevious, 51U)) + 0xE85A44B3B081659EULL;
            aOrbiterE = ((aWandererK + RotL64(aCross, 23U)) + 0xF5F2048658F8CFD2ULL) + aOASaltB[((aIndex + 29U)) & S_SALT1];
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x79D2DE6EE5DAB87CULL) + aOUSaltA[(((511U - aIndex) + 83U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xCF02B4C1DB177C3BULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF7764454D7036827ULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x396E1DE96F661BFBULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xBD9EB4B53D7DED74ULL) ^ aOUSaltH[((aIndex + 442U)) & S_SALT1];
