            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x9571C1432F8A7C36ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x8224B2D3F8AD54CBULL;
            aOrbiterH = RotL64((aOrbiterH * 0x993D14ED59BE5277ULL), 27U);
