            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x5A2A6D6F51790A31ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterE) ^ 0xDBC8F47ED4138CDEULL) ^ aOUSaltA[((aIndex + 511U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x8D3347D6A9E5B05BULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xF3B8BE57C82E3872ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x425066A219C29438ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x8574152B96631FA9ULL), 19U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0xA4F2DC856140D938ULL) + aOUSaltC[((aIndex + 461U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x813FA8895089A5E2ULL) ^ aOUSaltE[((aIndex + 295U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x5170FBE523F19C37ULL), 57U);
            //
            aIngress = RotL64(aOrbiterF, 51U) ^ aOrbiterD;
