            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = ((aWandererJ + RotL64(aScatter, 38U)) + 0x60C767AD1810A5B3ULL) + aOASaltA[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = (((aWandererB + RotL64(aIngress, 11U)) + RotL64(aCarry, 57U)) + 0xA1C6B74E410427CDULL) + aOASaltE[(((511U - aIndex) + 51U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aPrevious, 29U)) + 0xB37541642DE68C36ULL) + aOASaltB[((aIndex + 73U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aCross, 3U)) + RotL64(aCarry, 11U)) + 0x27077CC3ED4B681EULL) + aOASaltD[(((511U - aIndex) + 97U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aScatter, 47U)) + RotL64(aCarry, 27U)) + 0x8DAD3431B60F1DAEULL;
            aOrbiterG = ((aWandererE + RotL64(aIngress, 21U)) + 0x72E07C74D583DAFAULL) + aOASaltG[(((511U - aIndex) + 248U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aCross, 57U)) + 0x7DF44B7A9A6B192FULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterC) + 0xF6E40B1CEEDE80ACULL) + aOUSaltC[((aIndex + 138U)) & S_SALT1];
