            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0xA4AE55EBFB3DC296ULL) + aOUSaltA[((aIndex + 448U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x42FAF20C08CFE4ADULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC9932038F3A6866FULL), 51U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x0E16461696451C08ULL) + aOUSaltE[((aIndex + 67U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0xE0EBF60368AB1482ULL) ^ aOUSaltD[(((511U - aIndex) + 190U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x9DD73ACBBF1F2DD1ULL), 3U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterF, 19U);
