    std::uint64_t *aOASaltB = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterAssign.mSaltB;
    std::uint64_t *aOASaltC = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterAssign.mSaltC;
