            aIngress ^= (RotL64(aLightningLaneB[((aIndex + 6161U)) & S_BLOCK1], 4U) ^ RotL64(aMagmaLaneC[((aIndex + 1126U)) & S_BLOCK1], 37U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
