            aCross ^= (RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 7915U)) & S_BLOCK1], 13U) ^ RotL64(aKeyRowReadB[((aIndex + 3478U)) & W_KEY1], 35U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 19U) ^ RotL64(aCross, 34U)) + (RotL64(aCarry, 47U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = ((aWandererK + RotL64(aScatter, 43U)) + RotL64(aCarry, 51U)) + 0x0E031212696B1A2DULL;
            aOrbiterF = (aWandererJ + RotL64(aIngress, 5U)) + 0x7E869E85E928D2C1ULL;
            aOrbiterI = (aWandererB + RotL64(aCross, 20U)) + 0x9AAA170BD30F73EAULL;
            aOrbiterC = ((aWandererG + RotL64(aPrevious, 53U)) + 0xEADDBE991C98BF02ULL) + aOASaltA[((aIndex + 375U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aScatter, 37U)) + 0x3BD35279CB751454ULL;
            aOrbiterH = (((aWandererH + RotL64(aCross, 29U)) + RotL64(aCarry, 37U)) + 0x8293F151B42449C4ULL) + aOASaltB[(((511U - aIndex) + 481U)) & S_SALT1];
            aOrbiterE = (((aWandererI + RotL64(aPrevious, 11U)) + RotL64(aCarry, 19U)) + 0x2E4C07D41229DC93ULL) + aOASaltC[(((511U - aIndex) + 39U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x13273ACB2944B0F1ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xEC8C8E464B828E5BULL) ^ aOUSaltF[(((511U - aIndex) + 84U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x44A9CED63A29A517ULL), 29U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x7D4A518852B338AAULL) + aOUSaltG[(((511U - aIndex) + 506U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterC) ^ 0x855542CD33D2C5E6ULL) ^ aOUSaltC[((aIndex + 88U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xB68275C38EE42581ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x751092E540712D3FULL;
