            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x291EE9846317CF84ULL) + aOUSaltE[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x65CD512F117214DEULL;
            aOrbiterF = RotL64((aOrbiterF * 0x01D9D3BCCA061B85ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x7CAB87A207250E8DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x6706B766CBC3387AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x91067071A1186A79ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xF0F03EE11861862EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x7A3BAA7A3D76DEF5ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xB37C542879DAB3F5ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x05320A0F84172D95ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x9C8572507DACAADBULL;
            aOrbiterH = RotL64((aOrbiterH * 0x12CCAC40D496B49BULL), 47U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 57U);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterF, 21U));
            aIngress = aIngress + (RotL64(aOrbiterH, 13U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterI, 37U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererG = aWandererG ^ (((RotL64(aCross, 35U) + aOrbiterG) + RotL64(aOrbiterE, 57U)) + aWUSaltH[(((511U - aIndex) + 453U)) & S_SALT1]);
            aWandererK = aWandererK + ((((RotL64(aIngress, 27U) + RotL64(aOrbiterE, 51U)) + aOrbiterF) + RotL64(aCarry, 35U)) + aWUSaltD[(((511U - aIndex) + 277U)) & S_SALT1]);
            aWandererH = aWandererH ^ (((RotL64(aScatter, 11U) + RotL64(aOrbiterH, 19U)) + aOrbiterK) + aWUSaltA[((aIndex + 30U)) & S_SALT1]);
            aWandererC = aWandererC + ((((RotL64(aPrevious, 4U) + aOrbiterH) + RotL64(aOrbiterI, 41U)) + RotL64(aCarry, 57U)) + aWUSaltB[((aIndex + 510U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterG, 10U)) + aOrbiterF);
