            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 8266U)) & S_BLOCK1], 3U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 15497U)) & S_BLOCK1], 21U));
            aCross ^= (RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 10497U)) & S_BLOCK1], 30U) ^ RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 12524U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 23U) + RotL64(aCross, 3U)) + (RotL64(aCarry, 37U) ^ RotL64(aPrevious, 54U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = (aWandererI + RotL64(aCross, 5U)) + 0xEE13320B426613BCULL;
            aOrbiterK = (((aWandererD + RotL64(aIngress, 41U)) + RotL64(aCarry, 23U)) + 0x0F4F3F7EEE2212BAULL) + aOASaltH[(((511U - aIndex) + 400U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aScatter, 47U)) + RotL64(aCarry, 5U)) + 0xE1C33B26404EED99ULL;
            aOrbiterA = (aWandererB + RotL64(aPrevious, 21U)) + 0x4937D16701B8584FULL;
            aOrbiterC = ((aWandererG + RotL64(aIngress, 35U)) + 0x6F94CAED40A1B9B1ULL) + aOASaltA[((aIndex + 222U)) & S_SALT1];
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 12U)) + 0x70EF161E5CA67B06ULL) + aOASaltE[(((511U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = (((aWandererH + RotL64(aCross, 29U)) + RotL64(aCarry, 39U)) + 0xB18F699A7DEA7F26ULL) + aOASaltC[(((511U - aIndex) + 508U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x25763387F06454E7ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x7EABF52BEA3E9B0AULL;
            aOrbiterE = RotL64((aOrbiterE * 0x7A543959DA06C0CBULL), 5U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x953787271842752DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x3716D93C105497C9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5BC7D65AF243DF6BULL), 47U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xF85FB06CBD132611ULL) + aOUSaltD[(((511U - aIndex) + 125U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x6BDC1DBEE1C90E96ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8DC152D68F3E95DFULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x4329CDE81789FC0BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x1D0F2450FB9D8E84ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x7430EF8B73A50647ULL), 35U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x18EBB74DA4B48C56ULL) + aOUSaltC[((aIndex + 380U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x0393BD1C937F6B71ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x63F48B3A26F4B44DULL), 29U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x578DEAED778245C0ULL) + aOUSaltH[(((511U - aIndex) + 205U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0x55BCFA5B3F9CD318ULL) ^ aOUSaltB[(((511U - aIndex) + 146U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x0C8D3155D0B96AEDULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x5E21F10D9444BDE1ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0x65AF9664FE15F9F1ULL) ^ aOUSaltG[((aIndex + 207U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x54E5BA78A7ACA99DULL), 53U);
            //
            aIngress = RotL64(aOrbiterC, 3U) ^ aOrbiterB;
            aIngress = aIngress + (RotL64(aOrbiterA, 43U) ^ aOrbiterI);
            aIngress = aIngress + (RotL64(aOrbiterD, 51U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterE, 60U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 19U) + RotL64(aOrbiterB, 35U)) + aOrbiterK);
            aWandererH = aWandererH + (((RotL64(aCross, 5U) + RotL64(aOrbiterA, 41U)) + aOrbiterI) + RotL64(aCarry, 27U));
            aWandererI = aWandererI ^ (((RotL64(aIngress, 27U) + RotL64(aOrbiterE, 11U)) + aOrbiterD) + aWUSaltH[(((511U - aIndex) + 117U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aScatter, 34U) + aOrbiterK) + RotL64(aOrbiterC, 5U)) + RotL64(aCarry, 39U));
